# -*- coding: utf-8 -*-"""手术前安全气囊编辑 dp_router.py 前的自动备份+编码检查用法python pre_op.py"""import shutil, os, sys, py_compilefrom datetime import datetimeTARGET = os.path.join(os.path.dirname(__file__), 'dp_router.py')BAK_DIR = os.path.join(os.path.dirname(__file__), '.surgical_backups')def run():    if not os.path.exists(TARGET):        print(f'[安全气囊] 目标不存在: {TARGET}')        return False        os.makedirs(BAK_DIR, exist_ok=True)    stamp = datetime.now().strftime('%Y%m%d_%H%M%S')        # 1. 备份    bak_path = os.path.join(BAK_DIR, f'dp_router_{stamp}.py')    shutil.copy2(TARGET, bak_path)    print(f'[安全气囊] OK  备份  {bak_path}')        # 2. 编译检查    try:        py_compile.compile(TARGET, doraise=True)        print(f'[安全气囊] OK  编译通过')    except py_compile.PyCompileError as e:        print(f'[安全气囊] X  编译失败备份已做可以回滚: {e}')        return False        # 3. 中文编码完整性检查    with open(TARGET, 'r', encoding='utf-8') as f:        content = f.read()        # 检查关键中文关键词是否被GBK损坏    critical_kw = ['呼吸', '身体扫描', '安全岛', '认知', '刺激控制']    for kw in critical_kw:        if kw not in content:            print(f'[安全气囊] X  关键词丢失: "{kw}"  文件可能GBK损坏')            return False        # 检查有无替代字符文件损坏的标记    if '\ufffd' in content:        print(f'[安全气囊] X  文件包含替代字符 \\ufffd  GBK串扰')        return False        print(f'[安全气囊] OK  中文完整性通过')        # 4. 显示文件大小变化趋势    size = os.path.getsize(TARGET)    print(f'[安全气囊]  文件大小: {size:,} 字节')        print(f'\n[安全气囊]  一切正常可以手术')    print(f'      回滚命令: copy {bak_path} {TARGET}')    return Trueif __name__ == '__main__':    run()